"""App factory. Part of the scaffold: agents do not edit this file.

Runs migrations at startup and registers every module in app/routers/ that defines `router`.
"""

from __future__ import annotations

import importlib
import pkgutil
from contextlib import asynccontextmanager

from fastapi import FastAPI

from app import auth, db
from app import routers as routers_pkg


def create_app() -> FastAPI:
    @asynccontextmanager
    async def lifespan(_: FastAPI):
        db.run_migrations()
        yield

    app = FastAPI(title="Generated app", lifespan=lifespan)
    app.include_router(auth.router)
    for info in sorted(pkgutil.iter_modules(routers_pkg.__path__), key=lambda i: i.name):
        module = importlib.import_module(f"app.routers.{info.name}")
        router = getattr(module, "router", None)
        if router is not None:
            app.include_router(router)
    return app


app = create_app()
